'use strict';
window.HRAssignmentList={mount(host,{config,employees,reload,request}){
 const $=id=>document.getElementById(id),label=r=>r==='supervisor'?'主管人員':r==='staff'?'一般職員':'未分配';let selected=new Set(),pending=new Map(),page=1,busy=false,version=0;
 host.innerHTML=`<h2>表單類型分配</h2><div class="field-grid"><div><label for="assignPeriod">考績期別</label><select id="assignPeriod"></select></div><div><label for="assignmentSearch">員工姓名／編號／部門</label><input id="assignmentSearch"></div><div><label for="assignmentDepartment">部門</label><select id="assignmentDepartment"><option value="">全部部門</option></select></div></div><div class="toolbar"><button type="button" id="assignmentSelectPage" class="secondary">勾選本頁</button><button type="button" id="assignmentSelectFiltered" class="secondary">勾選篩選結果</button><button type="button" id="assignmentClear" class="secondary">取消選取</button><span id="assignmentSelected"></span><label for="assignType">批次指定</label><select id="assignType"><option value="staff">一般職員</option><option value="supervisor">主管人員</option></select><button type="button" id="assignmentApply">套用至已選員工</button></div><div class="table-wrap"><table class="assignment-list"><thead><tr><th>選取</th><th>員工</th><th>部門</th><th>目前表單類型</th><th>調整表單類型</th><th>操作</th></tr></thead><tbody id="assignmentRows"></tbody></table></div><div class="toolbar"><button type="button" id="assignmentSave">儲存變更</button><button type="button" id="assignmentCancel" class="secondary">取消變更</button><span id="assignmentDirty"></span><button type="button" id="assignmentPrev" class="secondary">上一頁</button><span id="assignmentPage"></span><button type="button" id="assignmentNext" class="secondary">下一頁</button><label for="assignmentSize">每頁筆數</label><select id="assignmentSize"><option>10</option><option selected>20</option><option>50</option></select></div><p id="assignmentMessage" role="status"></p>`;
 for(const p of config.periods)$('assignPeriod').add(new Option(window.HRUI.period(p),p));$('assignPeriod').value=window.HRGoogleCache.getItem('stage11-assignment-period')||config.activePeriod;if(!$('assignPeriod').value)$('assignPeriod').value=config.activePeriod;
 const filter=()=>employees().filter(e=>(!$('assignmentSearch').value||[e.name,e.id,e.department].join(' ').includes($('assignmentSearch').value.trim()))&&(!$('assignmentDepartment').value||e.department===$('assignmentDepartment').value));
 const current=e=>e.assignments?.[$('assignPeriod').value]||'';
 function invalidate(){version++;window.HRManagementDrafts?.dirty[pending.size?'add':'delete']('assignmentPanel')}
 function render(){const rows=filter(),size=+$('assignmentSize').value,pages=Math.max(1,Math.ceil(rows.length/size));page=Math.min(pages,Math.max(1,page));$('assignmentRows').replaceChildren(...rows.slice((page-1)*size,page*size).map(e=>{const tr=document.createElement('tr');const cell=text=>{const td=document.createElement('td');if(text!==undefined)td.textContent=text;tr.append(td);return td};const check=document.createElement('input');check.type='checkbox';check.checked=selected.has(e.id);check.dataset.assignmentSelect=e.id;check.setAttribute('aria-label','選取 '+e.name);check.onchange=()=>{check.checked?selected.add(e.id):selected.delete(e.id);counts()};cell().append(check);cell(e.name+'\n'+e.id);cell(e.department);cell(label(current(e)));const type=document.createElement('select');type.setAttribute('aria-label',e.name+' 調整表單類型');type.dataset.assignmentType=e.id;for(const r of ['staff','supervisor'])type.add(new Option(label(r),r));type.value=pending.get(e.id)||current(e)||'staff';type.onchange=()=>{if(type.value===current(e))pending.delete(e.id);else pending.set(e.id,type.value);invalidate();counts()};cell().append(type);const save=document.createElement('button');save.type='button';save.textContent='儲存';save.dataset.assignmentSave=e.id;save.disabled=busy;save.onclick=()=>{if(!current(e)&&!pending.has(e.id)){pending.set(e.id,type.value);invalidate()}return saveChanges([e.id])};cell().append(save);return tr}));$('assignmentPage').textContent=page+' / '+pages+'（共 '+rows.length+' 人）';$('assignmentPrev').disabled=page===1||busy;$('assignmentNext').disabled=page===pages||busy;counts()}
 function counts(){$('assignmentSelected').textContent='已選 '+selected.size+' 人（保留跨頁選取）';$('assignmentDirty').textContent='未儲存 '+pending.size+' 人';$('assignmentSave').disabled=busy||!pending.size;$('assignmentApply').disabled=busy||!selected.size}
 function setBusy(value){busy=value;for(const e of host.querySelectorAll('button,input,select'))e.disabled=value;if(!value)render()}
 async function saveChanges(ids){if(busy)return;const changes=ids.filter(id=>pending.has(id));if(!changes.length){$('assignmentMessage').textContent='尚無表單類型變更。';return}const stamp=version,period=$('assignPeriod').value;setBusy(true);try{const groups=[];for(const formRole of ['staff','supervisor']){const employeeIds=changes.filter(id=>pending.get(id)===formRole);if(!employeeIds.length)continue;const body={employeeIds,period,formRole},plan=await request('/api/roster/assignment-preview',body);if(plan.impacts.some(i=>i.blocked))throw Error('包含已送出或歸檔資料，請先由有權限人事退回；未變更任何表單。');groups.push({...body,version:plan.version,impactConfirmed:true,impacts:plan.impacts})}if(stamp!==version)return;
 const details=groups.flatMap(g=>g.impacts.map(i=>(employees().find(e=>e.id===i.employeeId)?.name||i.employeeId)+'：'+label(i.oldType)+' → '+label(i.newType)+(i.hasData?'；舊草稿將封存，員工需重新填寫':i.enroll?'；納入本期':'')));
 if(!await window.HRUI.confirm('確定要將 '+changes.length+' 位員工分配至 '+period+' 嗎？其他期別與歷史紀錄保留。',{title:'確認表單分配',accept:'確認分配',details}))return;if(stamp!==version)return;
 await request('/api/roster/assign-changes',{groups:groups.map(({impacts,...g})=>g)});for(const id of changes)pending.delete(id);invalidate();await reload();$('assignmentMessage').textContent='已儲存 '+changes.length+' 位員工的分配，歷史資料保留。';window.HRUI.notify('表單分配已儲存。')
 }catch(e){$('assignmentMessage').textContent=e.message}finally{setBusy(false)}}
 for(const id of ['assignmentSearch','assignmentDepartment','assignmentSize'])$(id).addEventListener(id==='assignmentSearch'?'input':'change',e=>{if(e.isComposing)return;page=1;render()});$('assignmentSearch').addEventListener('compositionend',render);
 $('assignmentSelectPage').onclick=()=>{for(const x of $('assignmentRows').querySelectorAll('[data-assignment-select]'))selected.add(x.dataset.assignmentSelect);render()};$('assignmentSelectFiltered').onclick=()=>{for(const e of filter())selected.add(e.id);render()};$('assignmentClear').onclick=()=>{selected.clear();render()};$('assignmentApply').onclick=()=>{for(const id of selected){const e=employees().find(e=>e.id===id);if(!e)continue;if(current(e)===$('assignType').value)pending.delete(id);else pending.set(id,$('assignType').value)}invalidate();render()};$('assignmentSave').onclick=()=>saveChanges([...pending.keys()]);$('assignmentCancel').onclick=()=>{pending.clear();invalidate();render();$('assignmentMessage').textContent='已取消未儲存變更，已儲存資料與歷史紀錄不受影響。'};let previous=$('assignPeriod').value;
 $('assignPeriod').onchange=async()=>{const target=$('assignPeriod').value;$('assignPeriod').value=previous;if(pending.size&&!await window.HRUI.confirm('切換期別將取消目前未儲存的分配變更，確定繼續？'))return;$('assignPeriod').value=target;previous=target;window.HRGoogleCache.setItem('stage11-assignment-period',target);pending.clear();invalidate();page=1;render()};$('assignmentPrev').onclick=()=>{page--;render()};$('assignmentNext').onclick=()=>{page++;render()};
 function refresh(){const old=$('assignmentDepartment').value;$('assignmentDepartment').replaceChildren(new Option('全部部門',''),...[...new Set(employees().map(e=>e.department))].map(d=>new Option(d,d)));$('assignmentDepartment').value=old;selected=new Set([...selected].filter(id=>employees().some(e=>e.id===id)));render()}
 refresh();return {refresh,select(ids){selected=new Set(ids);$('assignmentSearch').value=ids.length===1?ids[0]:'';page=1;render()}};
}};
